// Evita shift de fuso: colunas `date` (YYYY-MM-DD) não devem passar por
// new Date(string) — o JS interpreta como UTC meia-noite e recua 1 dia em UTC-3.
function parseISODateLocal(iso: string) {
  if (!iso) return new Date();
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(y, (m || 1) - 1, d || 1);
}

